import numpy as np, wave
def load(p):
    w = wave.open(p)
    return np.frombuffer(w.readframes(w.getnframes()), dtype=np.int16).reshape(-1,2)[:,0].astype(np.float64)/32768, w.getframerate()
def fpeak(x, sr, t0, t1):
    seg = x[int(t0*sr):int(t1*sr)]; n=len(seg); win=np.hanning(n)
    spec = np.abs(np.fft.rfft(seg*win)); i=np.argmax(spec)
    if 0<i<len(spec)-1:
        a,b,c = spec[i-1],spec[i],spec[i+1]; d=0.5*(a-c)/(a-2*b+c)
        return (i+d)*(sr/n)
    return i*(sr/n)
x, sr = load("m9.wav")
print("seg0:", round(fpeak(x,sr,0.01,0.11),1))
print("seg24:", round(fpeak(x,sr,0.25,0.35),1))
EOF"}

