import struct, numpy as np, subprocess, json
sr = 8363
cycle = 31
t = np.arange(cycle, dtype=np.float64)/sr
wav = (0.7*32767*np.sin(2*np.pi*261.6256*t)).astype('<i2')
def ljust(s, n):
    if isinstance(s, str): s = s.encode()
    return s + b'\0'*(n-len(s))
def cell(note=None, ins=None, vol=None, eff=None, par=None):
    f = 0; out = bytearray()
    if note is not None: f|=1; out.append(note)
    if ins is not None: f|=2; out.append(ins)
    if vol is not None: f|=4; out.append(vol)
    if eff is not None: f|=8; out.append(eff)
    if par is not None: f|=16; out.append(par)
    return bytes([0x80|f]) + bytes(out)
def make_xm(fade, fname, pts=[(0,64)], sus=0):
    data = b""
    data += b"Extended Module: " + ljust("ft",20) + b"\x1a" + ljust("Python XM writer",20)
    data += struct.pack("<H", 0x0104)
    data += struct.pack("<I", 276) + struct.pack("<HHHHHH", 1,0,2,1,1,1) + struct.pack("<HH", 6,125)
    data += bytes(256)
    rows = 64
    packed = bytearray()
    for r in range(rows):
        for ch in range(2):
            if r == 0 and ch == 0: packed += cell(note=49, ins=1)
            elif r == 40 and ch == 0: packed += cell(note=97)
            else: packed += bytes([0x80])
    data += struct.pack("<I", 9) + bytes([0]) + struct.pack("<H", rows) + struct.pack("<H", len(packed)) + bytes(packed)
    ins = b""
    ins += struct.pack("<I", 263) + ljust("i",22) + bytes([1]) + struct.pack("<H",1) + struct.pack("<I",40)
    ins += bytes(96)
    volenv = bytearray(48)
    for i,(x,y) in enumerate(pts):
        volenv[i*4:i*4+4] = struct.pack("<HH", x, y)
    ins += bytes(volenv) + bytes(48)
    ins += bytes([len(pts), 0, sus, 0, 0, 0, 0, 0])
    ins += bytes([1, 0]) + bytes([0,0,0,0]) + struct.pack("<H", fade) + bytes(22)
