#!/usr/bin/env python3
import numpy as np, base64, json, subprocess, struct, os

SR = 8363
C4 = 261.625565
NAMES = ['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']
def n2s(pc, octv): return f"{NAMES[pc]}{octv}"

def norm(x, peak=0.85):
    m = np.max(np.abs(x))
    if m == 0: return x
    return (x/m*peak*32767).astype(np.int16)
def hp(x): return np.concatenate([[0], np.diff(x)])
def saw_cycle(freq, nharm=15, roll=1.0):
    t = np.arange(int(round(SR/freq)), dtype=np.float64)/SR
    x = np.zeros_like(t)
    for k in range(1, nharm+1): x += np.sin(2*np.pi*k*freq*t)/(k**roll)
    return x
def square_cycle(freq, nharm=8):
    t = np.arange(int(round(SR/freq)), dtype=np.float64)/SR
    x = np.zeros_like(t)
    for k in range(1, nharm+1): x += np.sin(2*np.pi*(2*k-1)*freq*t)/(2*k-1)
    return x

def make_samples():
    S = {}
    rng = np.random.default_rng(7)
    n = int(0.28*SR); t = np.arange(n)/SR
    f = 46 + 118*np.exp(-t/0.045)
    x = np.sin(2*np.pi*np.cumsum(f)/SR)*np.exp(-t/0.095)
    x[:14] += 0.5*rng.standard_normal(14)*np.linspace(1,0,14)
    S['kick'] = norm(np.tanh(1.5*x), 0.88)
    n = int(0.25*SR); t = np.arange(n)/SR
    S['snare'] = norm(0.6*np.sin(2*np.pi*192*t)*np.exp(-t/0.05) + 0.85*hp(rng.standard_normal(n))*np.exp(-t/0.075), 0.85)
    n = int(0.06*SR); t = np.arange(n)/SR
    S['hatc'] = norm(hp(rng.standard_normal(n))*np.exp(-t/0.014), 0.78)
    n = int(0.35*SR); t = np.arange(n)/SR
    S['hato'] = norm(hp(rng.standard_normal(n))*np.exp(-t/0.10), 0.72)
    n = int(1.7*SR); t = np.arange(n)/SR
    nz = rng.standard_normal(n)
    S['crash'] = norm((0.7*hp(nz)+0.5*nz)*np.exp(-t/0.55), 0.7)
    S['bass'] = norm(saw_cycle(C4, 15), 0.8)
    S['lead'] = norm(square_cycle(C4, 8), 0.75)
    S['harm'] = norm(saw_cycle(C4, 12, 1.25), 0.72)
    n = int(0.12*SR); t = np.arange(n)/SR
    x = np.zeros(n)
    for k in range(1,16): x += np.sin(2*np.pi*k*C4*t)/k
    S['arp'] = norm(x*np.exp(-t/0.026), 0.7)
    S['pad'] = norm(saw_cycle(C4, 6, 1.6), 0.6)
    n = int(0.35*SR); t = np.arange(n)/SR
    f = 150 + 780*np.exp(-t/0.055)
    S['zap'] = norm((np.sin(2*np.pi*np.cumsum(f)/SR)+0.35*np.sin(4*np.pi*np.cumsum(f)/SR))*np.exp(-t/0.12), 0.7)
    return S

# instruments: 1 kick,2 snare,3 hatc,4 hato,5 crash,6 bass,7 lead,8 harm,9 arp,10 pad,11 zap
INS = {'kick':1,'snare':2,'hatc':3,'hato':4,'crash':5,'bass':6,'lead':7,'harm':8,'arp':9,'pad':10,'zap':11}
# channels
CH = {'kick':0,'snare':1,'hatc':2,'hato':3,'crash':4,'bass':5,'arp':6,'arp2':7,'lead':8,'harm':9,'pad':10,'zap':11}
BPM, SPEED = 136, 6
NPAT = 6
ROWS = 64

# chord roots (note strings)
CHORDS = [
  [('A-2','min'),('F-2','maj'),('C-2','maj'),('G-2','maj')],   # P0
  [('A-2','min'),('F-2','maj'),('C-2','maj'),('G-2','maj')],   # P1
  [('D-2','min'),('F-2','maj'),('C-2','maj'),('E-2','maj')],   # P2
  [('F-2','maj'),('G-2','maj'),('A-2','min'),('E-2','maj')],   # P3
  [('A-2','min'),('F-2','maj'),('C-2','maj'),('G-2','maj')],   # P4
  [('F-2','maj'),('G-2','maj'),('C-2','maj'),('E-2','maj')],   # P5
]
# bass fill (last bar of each pattern): rows 12..15 walk to next pattern's first root
BASSFILL = {
 0: ['A-2','G-2','F#2','F-2'],
 1: ['F-2','E-2','D-2','C-2'],
 2: ['C-2','D-2','E-2','F-2'],
 3: ['F-2','E-2','D-2','C-2'],
 4: ['C-2','D-2','E-2','F#2'],
 5: ['E-2','F-2','G-2','G#2'],
}
BASSFILLUP = {2: True, 4: True, 5: True}  # ascending fills
def bass_events(p):
    ev = []
    for b in range(4):
        root, kind = CHORDS[p][b]
        R2 = root  # octave 2
        pc, octv = root[0:2] if root[1] in '-#' else root[0], None
        # parse
        i = 0
        name = root
        for k, nm in enumerate(NAMES):
            if root.startswith(nm):
                pc, octv = k, int(root[len(nm):]); break
        R3 = n2s(pc, octv+1)
        if b < 3:
            groove = [(0,R2,58),(2,R3,50),(3,R2,54),(4,R2,58),(6,R3,50),(7,R2,54),
                      (8,R2,58),(10,R3,50),(11,R2,54),(12,R3,50),(13,R2,54),(14,R3,50),(15,R2,54)]
        else:
            fill = BASSFILL[p]
            groove = [(0,R2,58),(2,R3,50),(3,R2,54),(4,R2,58),(6,R3,50),(7,R2,54),(8,R2,58),(10,R3,50),(11,R2,54)]
            for i,f in enumerate(fill):
                groove.append((12+i, f, 56 if i==3 else 54))
        for r, nn, v in groove:
            ev.append((bar(r,b), nn, v))
    return ev

def hat_events(p):
    ev = []
    for b in range(4):
        if p in (0,5):
            for r in (2,6,10,14): ev.append((bar(r,b),'hatc',40))
        elif p == 3:
            if b < 2:
                for r in (2,6,10,14): ev.append((bar(r,b),'hatc',40))
            elif b == 2:
                for r in (2,6,10,14): ev.append((bar(r,b),'hatc',44))
            else:
