        ev += [(bar(12,2),'snare',44),(bar(12,3),'snare',46),(bar(14,3),'snare',42)]
    return ev

def crash_events(p):
    ev = []
    if p == 0: ev.append((0,'crash',34))
    if p == 1: ev.append((0,'crash',46))
    if p == 2: ev.append((0,'crash',36))
    if p == 3: ev.append((bar(0,3),'crash',44))
    if p == 4: ev.append((0,'crash',50))
    if p == 5: ev.append((0,'crash',32))
    return ev

def zap_events(p):
    ev = []
    if p in (0,2,4,5): ev.append((bar(14,3),'zap',46))
