        ev += [(bar(0,3),'B-4',56),(bar(3,3),'D-5',54),(bar(4,3),'E-5',58),(bar(7,3),'G#5',54),(bar(8,3),'E-5',56),(bar(11,3),'G#5',52),(bar(12,3),'B-4',54),(bar(14,3),'D-5',54),(bar(15,3),'E-5',56)]
    elif p == 3:
        ev += [(bar(8,2),'E-5',56),(bar(12,2),'D-5',52),(bar(14,2),'C-5',54)]
        ev += [(bar(0,3),'B-4',56),(bar(4,3),'E-5',58),(bar(8,3),'G#5',58),(bar(12,3),'G#5',54),(bar(14,3),'B-4',52),(bar(15,3),'C-5',56)]
    elif p == 4:
        ev += [(bar(0,0),'A-5',60),(bar(3,0),'C-5',54),(bar(4,0),'E-5',60),(bar(7,0),'G-5',56),(bar(8,0),'A-5',62),(bar(11,0),'G-5',56),(bar(12,0),'E-5',58),(bar(14,0),'C-5',54),(bar(15,0),'D-5',56)]
