        ev += [(bar(0,2),'E-5',58),(bar(3,2),'G-5',54),(bar(4,2),'A-5',60),(bar(7,2),'G-5',56),(bar(8,2),'E-5',58),(bar(11,2),'D-5',54),(bar(12,2),'C-5',56),(bar(15,2),'B-4',54)]
