        ev += [(bar(4,2),'E-5',54),(bar(8,2),'C-5',52),(bar(12,2),'G-4',54)]
        ev += [(bar(0,3),'E-4',52),(bar(4,3),'G#4',54),(bar(8,3),'B-4',56),(bar(12,3),'D-5',58),(bar(15,3),'E-5',56)]
