def harm_events(p):
    ev = []
    if p == 2:
        ev += [(bar(0,3),'G#4',52),(bar(4,3),'G#4',52),(bar(8,3),'B-4',54),(bar(12,3),'G#4',54)]
    if p == 4:
        ev += [(bar(0,0),'C-5',52),(bar(4,0),'C-5',52),(bar(8,0),'E-5',54),(bar(12,0),'C-5',52),(bar(14,0),'A-4',50)]
        ev += [(bar(0,1),'A-4',52),(bar(4,1),'A-4',52),(bar(8,1),'C-5',54),(bar(12,1),'F-4',52)]
        ev += [(bar(0,2),'C-5',52),(bar(4,2),'E-5',54),(bar(8,2),'C-5',52),(bar(12,2),'G-4',52)]
        ev += [(bar(0,3),'B-4',52),(bar(4,3),'B-4',52),(bar(8,3),'G-4',52),(bar(12,3),'B-4',54)]
