    S = {}
    rng = np.random.default_rng(7)
    n = int(0.28*SR); t = np.arange(n)/SR
    f = 46 + 118*np.exp(-t/0.045)
    x = np.sin(2*np.pi*np.cumsum(f)/SR)*np.exp(-t/0.095)
    x[:14] += 0.5*rng.standard_normal(14)*np.linspace(1,0,14)
    S['kick'] = norm(np.tanh(1.5*x), 0.88)
    n = int(0.25*SR); t = np.arange(n)/SR
    S['snare'] = norm(0.6*np.sin(2*np.pi*192*t)*np.exp(-t/0.05) + 0.85*hp(rng.standard_normal(n))*np.exp(-t/0.075), 0.85)
    n = int(0.06*SR); t = np.arange(n)/SR
    S['hatc'] = norm(hp(rng.standard_normal(n))*np.exp(-t/0.014), 0.78)
    n = int(0.35*SR); t = np.arange(n)/SR
    S['hato'] = norm(hp(rng.standard_normal(n))*np.exp(-t/0.10), 0.72)
    n = int(1.7*SR); t = np.arange(n)/SR
    nz = rng.standard_normal(n)
    S['crash'] = norm((0.7*hp(nz)+0.5*nz)*np.exp(-t/0.55), 0.7)
    S['bass'] = norm(saw_cycle(C4, 15), 0.8)
