    if p == 0: ev.append((0,'crash',34))
    if p == 1: ev.append((0,'crash',46))
    if p == 2: ev.append((0,'crash',36))
    if p == 3: ev.append((bar(0,3),'crash',44))
    if p == 4: ev.append((0,'crash',50))
    if p == 5: ev.append((0,'crash',32))
    return ev

def zap_events(p):
    ev = []
    if p in (0,2,4,5): ev.append((bar(14,3),'zap',46))
    return ev

# arp: root octave 3, arp effect 0x37 minor / 0x47 major (cycle 1-5-3 in this engine)
def arp_events(p):
    ev = []
    for b in range(4):
        root, kind = CHORDS[p][b]
        for k, nm in enumerate(NAMES):
            if root.startswith(nm):
                pc, octv = k, int(root[len(nm):]); break
        r3 = n2s(pc, 3)
        par = 0x37 if kind=='min' else 0x47
        if p == 0:
            if b < 2:
                for r in (0,2,4,6,8,10,12,14): ev.append((bar(r,b),r3,44,0,par))
            else:
                for r in range(16): ev.append((bar(r,b),r3,46 if r%4==0 else 34,0,par))
        elif p == 3:
            if b < 3:
                for r in range(16): ev.append((bar(r,b),r3,46 if r%4==0 else 34,0,par))
            else:
                seq = [('E-3',0),('G#3',2),('B-3',4),('E-4',6),('G#4',8),('B-4',10),('E-5',12),('G#5',14)]
                for r,nn in seq: ev.append((bar(r,b),nn,50))
        elif p == 2 and b == 3:
            seq = [('E-3',0),('G#3',2),('B-3',4),('E-4',6),('G#4',8),('B-4',10),('E-5',12),('G#5',14)]
            for r,nn in seq: ev.append((bar(r,b),nn,50))
        elif p == 5:
            if b < 3:
                for r in (0,2,4,6,8,10,12,14): ev.append((bar(r,b),r3,44,0,par))
            else:
                seq = [('E-3',0),('G#3',2),('B-3',4),('E-4',6),('G#4',8),('B-4',10),('E-5',12),('G#5',14)]
                for r,nn in seq: ev.append((bar(r,b),nn,50))
        else: # p1, p4: dense
            for r in range(16): ev.append((bar(r,b),r3,48 if r%4==0 else 32,0,par))
    return ev

def arp2_events(p):
    ev = []
    if p in (0,4):
        for b in range(4):
            root, kind = CHORDS[p][b]
            for k, nm in enumerate(NAMES):
                if root.startswith(nm):
                    pc, octv = k, int(root[len(nm):]); break
            r4 = n2s(pc, 4)
            par = 0x37 if kind=='min' else 0x47
            if p == 0 and b < 2: continue
            for r in range(16): ev.append((bar(r,b),r4,36 if r%4==0 else 24,0,par))
    return ev

