# ---------------- build ----------------
def build_batch(S):
    calls = []
    calls.append({"name":"module_new","arguments":{"channels":12,"name":"neon keygen"}})
    calls.append({"name":"song_set","arguments":{"bpm":BPM,"speed":SPEED,"length":NPAT,"loop_start":0,"channels":12}})
    for i in range(NPAT):
        calls.append({"name":"pattern_set_length","arguments":{"pattern":i,"rows":ROWS}})
        calls.append({"name":"order_set","arguments":{"position":i,"pattern":i}})
    volmap = {'kick':60,'snare':52,'hatc':40,'hato':36,'crash':44,'bass':54,'lead':58,'harm':50,'arp':46,'pad':40,'zap':48}
    panmap = {'kick':128,'snare':120,'hatc':150,'hato':106,'crash':128,'bass':128,'lead':116,'harm':140,'arp':96,'pad':128,'zap':128}
    for name in ['kick','snare','hatc','hato','crash','bass','lead','harm','arp','pad','zap']:
        pcm = S[name]
        calls.append({"name":"sample_create_from_pcm","arguments":{
            "instrument":INS[name],"pcm":base64.b64encode(pcm.tobytes()).decode(),
            "encoding":"int16","name":name}})
        meta = {"instrument":INS[name],"sample":0,"volume":volmap[name],"panning":panmap[name]}
        if name in ('bass','lead','harm','pad'):
            cyc = len(pcm)
            meta["loop_start"] = 0
            meta["loop_length"] = cyc
            meta["flags"] = 17
        calls.append({"name":"sample_set","arguments":meta})
    # pattern cells
    for p in range(NPAT):
        for chname, ch in CH.items():
            for (row, note, vol, *rest) in track_events(p, chname):
                d = {"pattern":p,"row":row,"channel":ch,"note":note,"instrument":INS[chname],"volume":vol}
                if rest and rest[0] is not None:
                    d["effect"] = rest[0]
                    d["effect_param"] = rest[1] if len(rest)>1 and rest[1] is not None else 0
                calls.append({"name":"pattern_set_cell","arguments":d})
    return calls

# ---------------- envelope patch ----------------
ENV = {
 6: ([(0,64)], 0, 4096),                      # bass: instant on, fast release
 7: ([(0,0),(1,64),(4,36)], 2, 2048),         # lead pluck sustain
 8: ([(0,0),(1,56),(4,30)], 2, 2048),         # harmony
 10: ([(0,0),(12,40),(24,34)], 2, 1024),      # pad slow attack
}
def patch_xm(path, out):
    data = bytearray(open(path,'rb').read())
    numpat = struct.unpack("<H", data[70:72])[0]
    nins = struct.unpack("<H", data[72:74])[0]
    off = 336
    for _ in range(numpat):
        ph = struct.unpack("<I", data[off:off+4])[0]
        pds = struct.unpack("<H", data[off+7:off+9])[0]
        off += ph + pds
    for ii in range(nins):
        ins_no = ii + 1
        isz = struct.unpack("<I", data[off:off+4])[0]
        if ins_no in ENV:
            pts, sus, fade = ENV[ins_no]
            data[off+26] = 1
            ve = bytearray(48)
            for i,(x,y) in enumerate(pts):
                ve[i*4:i*4+4] = struct.pack("<HH", x, y)
            data[off+129:off+177] = ve
            data[off+225] = len(pts)
            data[off+227] = sus
            data[off+233] = 1
            data[off+239:off+241] = struct.pack("<H", fade)
        off += isz
    open(out,'wb').write(data)

def main():
    S = make_samples()
    calls = build_batch(S)
    open('/workspace/calls.json','w').write(json.dumps(calls))
    print(f"{len(calls)} calls, samples sizes: " + ", ".join(f"{k}={len(v)}" for k,v in S.items()))
    r = subprocess.run(['ft2','batch','/workspace/calls.json'], capture_output=True, text=True)
    print(r.stdout[-2000:])
    r = subprocess.run(['ft2','call','module_save', json.dumps({"path":"/workspace/submission/tune.xm","format":"xm"})], capture_output=True, text=True)
    print(r.stdout)
    patch_xm('/workspace/submission/tune.xm','/workspace/submission/tune.xm')
    print("patched envelopes")

if __name__ == '__main__':
    main()
